import {config} from './config.js';
import {personalFeedback} from './personalization.js';
import {persistProfile} from './api.js';

export function createExperience({state,ui,setProfile}){
 const {icon,esc,num,longTime,dateLabel,timeLabel,shortTime,localDate,metric,colors,units,metricNames,pageTitle,dials,refreshControl,insightCard,monitors,dailyActivities,activityRow,featuredSport,planCard,trendCard,lineChart,openDialog,navigate,toast}=ui;
 const demo=()=>config.mode==='demo',numeric=n=>typeof n==='number'&&Number.isFinite(n);
 Object.assign(metricNames,{weeklyIntensityMinutes:'Weekly intensity minutes',activeCalories:'Active energy',restingCalories:'Resting energy',hydrationMl:'Water logged',hydrationGoalMl:'Hydration goal',minHr:'Lowest heart rate',maxHr:'Highest heart rate',bodyBatteryCharged:'Energy gained',bodyBatteryDrained:'Energy used',stepsGoal:'Step goal',stressRestMinutes:'Restful time',stressHighMinutes:'High-stress time',sleepAvgHr:'Sleeping heart rate',sleepRespiration:'Sleep breathing rate',sleepPulseOx:'Sleep blood oxygen',sleepStress:'Sleep stress',awakeCount:'Awakenings'});
 Object.assign(units,{weeklyIntensityMinutes:'min',activeCalories:'kcal',restingCalories:'kcal',hydrationMl:'ml',hydrationGoalMl:'ml',minHr:'bpm',maxHr:'bpm',bodyBatteryCharged:'points',bodyBatteryDrained:'points',stepsGoal:'steps',stressRestMinutes:'min',stressHighMinutes:'min',sleepAvgHr:'bpm',sleepRespiration:'brpm',sleepPulseOx:'%',sleepStress:'/100',awakeCount:'times'});
 const explanations={steps:'Steps recorded for this day.',activeCalories:'Energy Garmin estimates from activity. This is not a food target.',calories:'Total energy estimated by Garmin, including resting and active energy.',restingCalories:'Garmin’s estimated energy used at rest.',hrv:'Variation in time between heartbeats during sleep. Compare your own multi-night trend.',restingHr:'Your recorded resting heart rate. A single change is not a fitness verdict.',bodyBattery:'Garmin’s estimate of energy reserves, from 0 to 100. It is different from Training Readiness.',bodyBatteryCharged:'Body Battery points gained through rest and sleep today.',bodyBatteryDrained:'Body Battery points used through activity and stress today.',stress:'Garmin’s daily average stress score, based on heart-rate variability.',stressRestMinutes:'Time Garmin classified as restful.',stressHighMinutes:'Time Garmin classified as high stress.',hydrationMl:'Water logged in Garmin Connect. Your band does not measure how much you drink.',sleepScore:'Garmin’s sleep score. Duration, stages and sleep quality provide context.',sleepMinutes:'Recorded time asleep, excluding awake time.',sleepAvgHr:'Average heart rate during the recorded sleep period.',respiration:'Average breaths per minute recorded during the day.',sleepRespiration:'Average breaths per minute during sleep.',pulseOx:'Recorded oxygen saturation estimate; availability depends on device settings.',sleepPulseOx:'Average oxygen saturation recorded during sleep.',intensityMinutes:'Moderate activity minutes plus twice vigorous minutes, as Garmin reports them.',vo2max:'Garmin’s recorded VO₂ max estimate, when available.',napMinutes:'Time in naps recorded by Garmin.',sleepStress:'Average recorded stress during sleep.',awakeCount:'Awakenings detected during the recorded sleep period.'};
 function header(){const {day,selectedDate,snapshot,profile}=state(),dates=day?.availableDates||[],index=dates.indexOf(selectedDate),today=localDate(new Date().toISOString(),snapshot?.timezone||'America/Panama');return `<header class="app-header"><div class="top-row"><button class="brand" data-page="home" aria-label="Home">CIRQA<span class="brand-dot"></span></button><div class="date-switch" aria-label="Selected day"><button data-date-step="-1" ${index<=0?'disabled':''} aria-label="Previous day">${icon('back')}</button><button class="date-label" data-action="calendar" ${dates.length?'':'disabled'}>${selectedDate===today?'TODAY':dateLabel(selectedDate).toUpperCase()}</button><button data-date-step="1" ${index<0||index>=dates.length-1?'disabled':''} aria-label="Next day">${icon('chevron')}</button></div><button class="profile" data-page="profile" aria-label="Personal profile">${esc(profile.displayName?profile.displayName.slice(0,2).toUpperCase():'YOU')}</button></div>${demo()?'<div class="demo-banner">Interactive demo · fictional measurements</div>':''}</header>`;}
 function dailyTiles(){return `<div class="focus-grid">${['steps','hrv','restingHr','activeCalories'].map(k=>`<button class="focus-tile" data-metric="${k}"><span>${metricNames[k]}</span><strong>${num(metric(k),k==='hrv'?1:0)} <small>${units[k]||''}</small></strong><em>${k==='steps'?'Your daily movement':k==='hrv'?'Overnight recovery signal':k==='restingHr'?'At rest':'Recorded by Garmin'}</em></button>`).join('')}</div>`;}
 function bodyBatteryChart(){const {snapshot,selectedDate}=state();const points=(snapshot.bodyBatterySeries||[]).filter(p=>localDate(p.timestamp,snapshot.timezone)===selectedDate).map(p=>({time:Date.parse(p.timestamp),value:p.value,label:shortTime(p.timestamp),tooltip:timeLabel(p.timestamp)+' · '+num(p.value)+' Body Battery'}));if(!points.length)return '';return `<section class="card trend-card battery-timeline"><div class="card-head"><div><h2>Energy through your day</h2><p>Body Battery · recorded points</p></div>${icon('bolt')}</div><div class="charge-row"><span>+${num(metric('bodyBatteryCharged'))} gained</span><span>−${num(metric('bodyBatteryDrained'))} used</span></div>${lineChart(points,{color:colors.recovery,id:'body-battery-day',timeSeries:true,min:0,max:100,area:true})}</section>`;}
 function home(){const {snapshot,goals,profile,day,selectedDate}=state(),feedback=personalFeedback(snapshot,goals,profile,selectedDate)[0]||day.primaryInsight;return `<div class="welcome"><div><span class="eyebrow">${dateLabel(selectedDate,{weekday:'long',month:'long',day:'numeric'})}</span><h1>${profile.displayName?'Your day, '+esc(profile.displayName)+'.':'Your day, at a glance.'}</h1><p>Your training. Your recovery. A clearer next step.</p></div><button class="connection-pill" data-page="device">${icon('band')}${demo()?'Demo':'Garmin connected'}</button></div><div class="home-layout"><section class="home-primary">${dials()}${refreshControl()}${insightCard(feedback,{compact:false,label:demo()?'DEMO FEEDBACK':'FOR YOU · CALCULATED'})}<div class="section-heading"><h2>In focus</h2><button data-page="metrics">All measurements ${icon('chevron')}</button></div>${dailyTiles()}${monitors()}<div class="section-heading"><h2>Your activities</h2><button data-page="history">History ${icon('chevron')}</button></div>${dailyActivities()}</section><section class="home-secondary">${featuredSport()}${planCard()}<div class="section-heading"><h2>Your trends</h2><button data-action="baseline-info" aria-label="About personal baselines">${icon('info')}</button></div>${trendCard()}${bodyBatteryChart()}<button class="history-banner" data-page="history">${icon('calendar')}<span><strong>${snapshot.activities.length} recorded workouts</strong><small>${demo()?'Fictional demo history':snapshot.coverage?.earliestWorkout?'History from '+dateLabel(snapshot.coverage.earliestWorkout):'Your available Garmin history'}</small></span>${icon('chevron')}</button></section></div>`;}
 function history(){const {snapshot}=state();return `${pageTitle('YOUR WORKOUT HISTORY','training')}<p class="page-intro">${snapshot.activities.length} workouts across all sports. Open a session to compare it with earlier workouts in the same category.</p><label class="field archive-search"><span>Find an activity</span><input id="archive-search" type="search" placeholder="Search sport or activity" autocomplete="off"></label><section class="card activity-card archive-list">${snapshot.activities.map(a=>`<div class="archive-entry" data-search="${esc((a.type+' '+a.name).toLowerCase())}"><p class="archive-date">${dateLabel(a.date,{weekday:'short',month:'short',day:'numeric',year:'numeric'})}</p>${activityRow(a)}</div>`).join('')}</section><p id="archive-empty" class="empty-note" hidden>No matching workouts.</p>`;}
 function sleepExtras(){return `<section class="card extra-card"><div class="card-head"><h2>While you slept</h2>${icon('moon')}</div>${['sleepAvgHr','sleepRespiration','sleepPulseOx','sleepStress','napMinutes'].filter(k=>numeric(metric(k))).map(k=>`<button class="measurement-row" data-metric="${k}"><span>${metricNames[k]}</span><strong>${num(metric(k),1)} <small>${units[k]}</small></strong>${icon('chevron')}</button>`).join('')||'<p class="data-note">Additional readings were not supplied for this day.</p>'}</section>`;}
 function stressDetails(){return `<div class="detail-stat-row">${[['stressRestMinutes','Restful time'],['stressHighMinutes','High stress'],['stress','Average stress']].map(([k,label])=>`<div class="detail-stat"><strong>${num(metric(k))}<small>${units[k]}</small></strong><span>${label}</span></div>`).join('')}</div>`;}
 function workoutExtras(a){const values=[['Distance',a.distanceKm,'km'],['Active time',a.movingDurationSec==null?null:a.movingDurationSec/60,'min'],['Elapsed time',a.elapsedDurationSec==null?null:a.elapsedDurationSec/60,'min'],['Energy',a.calories,'kcal'],['Body Battery change',a.bodyBatteryImpact,'points'],['Elevation gain',a.elevationM,'m'],['Average speed',a.averageSpeedMps==null?null:a.averageSpeedMps*3.6,'km/h'],['Maximum speed',a.maxSpeedMps==null?null:a.maxSpeedMps*3.6,'km/h'],['Cadence',a.avgCadence,'steps/min'],['Moderate intensity',a.moderateMinutes,'min'],['Vigorous intensity',a.vigorousMinutes,'min'],['Recorded laps',a.lapCount,'']].filter(([,v])=>numeric(v));return `<section class="card extra-card"><div class="card-head"><h2>Session details</h2>${icon('activity')}</div>${values.map(([label,value,unit])=>`<div class="measurement-row"><span>${label}</span><strong>${num(value,1)} <small>${unit}</small></strong></div>`).join('')}<p class="data-note">Recorded activity data. Garmin energy values are estimates.</p></section>`;}
 function metrics(){const {selectedDate,snapshot}=state(),available=Object.keys(metricNames).filter(k=>metric(k)!=null);return `${pageTitle('ALL MEASUREMENTS','more')}<p class="page-intro">${available.length} recorded readings for ${dateLabel(selectedDate)}. Tap a measurement to understand it.</p><div class="measurements-grid">${available.map(k=>`<button class="card measurement-card" data-metric="${k}"><span>${metricNames[k]}</span><strong>${typeof metric(k)==='string'?esc(metric(k).replaceAll('_',' ')):num(metric(k),1)} <small>${units[k]||snapshot.metrics[k]?.unit||''}</small></strong><p>${esc(explanations[k]||'Reported by Garmin for the selected day.')}</p>${icon('chevron')}</button>`).join('')}</div><button class="section-link" data-page="device"><span>Device features and data availability</span>${icon('chevron')}</button>`;}
 function profileView(){const {profile,snapshot}=state();return `${pageTitle('YOUR PROFILE','more')}<div class="form-panel"><div class="goal-hero"><span class="eyebrow">PERSONALIZE YOUR TRAINING</span><h2>Your goals start with you.</h2><p>Your profile puts sleep, recovery and training in context.</p></div><form id="profile-form"><div class="form-grid"><label class="field wide"><span>Name or nickname</span><input name="displayName" maxlength="40" autocomplete="given-name" value="${esc(profile.displayName)}"></label>${[['age','Age','years',13,100,1],['heightCm','Height','cm',100,240,.1],['weightKg','Weight','kg',25,250,.1]].map(([key,label,unit,min,max,step])=>`<label class="field"><span>${label} · ${unit}</span><input type="number" inputmode="decimal" name="${key}" min="${min}" max="${max}" step="${step}" value="${profile[key]??''}"></label>`).join('')}<label class="field"><span>Main sport</span><input name="preferredSport" maxlength="40" value="${esc(profile.preferredSport)}" list="sport-list"><datalist id="sport-list">${[...new Set(snapshot.activities.map(a=>a.type))].map(t=>`<option value="${esc(t)}">`).join('')}</datalist></label></div>${profile.age&&profile.age<18?'<div class="profile-context">Teen training profile · sleep guidance uses 8–10 hours. Plan intense training with your coach and allow time for recovery.</div>':''}<p class="form-error" id="profile-error" role="alert"></p><div class="form-actions"><button class="button-secondary" type="button" data-page="more">Back</button><button class="button-primary" type="submit">Save profile ${icon('check')}</button></div></form><p class="subtle-note">${demo()?'Demo profile stays in this browser.':'Your profile is saved privately with your dashboard.'}</p></div>`;}
 function connection(){openDialog('Your feedback, explained','<p>Comparisons and personalized feedback run inside this app using your recorded data and profile. They do not need a Grok bot and are labeled “calculated.”</p><p>Generative AI is optional. It requires a connected model; your Garmin API key grants Garmin access only.</p><p>Saved information appears first. This page checks on opening, every 30 minutes while visible, and when you press Refresh. If there is no new data, the saved information stays in place.</p><a class="dialog-link" href="./docs/CONNECTION_WORKFLOW.md" download>Connection workflow</a><a class="dialog-link" href="./docs/GROK_BOT_PROMPT.md" download>Optional AI prompt</a>');}
 document.addEventListener('input',event=>{if(event.target.id!=='archive-search')return;const query=event.target.value.toLowerCase().trim();let count=0;document.querySelectorAll('.archive-entry').forEach(row=>{row.hidden=!row.dataset.search.includes(query);if(!row.hidden)count++;});document.getElementById('archive-empty').hidden=count>0;});
 document.addEventListener('submit',async event=>{
  if(event.target.id!=='profile-form')return;event.preventDefault();const {profile}=state(),form=event.target,button=form.querySelector('[type=submit]'),data=new FormData(form);
  const next={...profile,version:profile.version+1,displayName:String(data.get('displayName')).trim(),preferredSport:String(data.get('preferredSport')).trim(),...Object.fromEntries(['age','heightCm','weightKg'].map(k=>[k,data.get(k)===''?null:Number(data.get(k))]))};
  button.disabled=true;try{setProfile(await persistProfile(next));navigate('home');toast('Profile saved. Your feedback now uses it.');}catch{document.getElementById('profile-error').textContent='Check your profile values and try again.';button.disabled=false;}
 });
 return {header,explanations,bodyBatteryChart,sleepExtras,stressDetails,workoutExtras,connection,views:{home,profile:profileView,metrics,history}};
}
